from typing import List
from collections import Counter

def numoffbt(arr: List[int], n: int) -> int:
    MOD = 1000000007
    arr = list(set(arr))  # Remove duplicates
    arr.sort()
    count = Counter(arr)
    dp = {x: count[x] for x in arr}

    for i in range(len(arr)):
        for j in range(i):
            if arr[i] % arr[j] == 0:
                right = arr[i] // arr[j]
                if right in dp:
                    dp[arr[i]] = (dp[arr[i]] + dp[arr[j]] * dp[right]) % MOD

    total = sum(dp.values()) % MOD
    return total
